import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o,c as a,a as r}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const m=JSON.parse(`{"title":"What's new in v1.6.0","description":"Power navigation shortcuts: global fold/unfold, Vim-style gg/G top/bottom jumps, paged scrolling with Page Up/Down and Ctrl+U/D, and open-in-browser for any result.","frontmatter":{"title":"What's new in v1.6.0","description":"Power navigation shortcuts: global fold/unfold, Vim-style gg/G top/bottom jumps, paged scrolling with Page Up/Down and Ctrl+U/D, and open-in-browser for any result.","date":"2026-03-02T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-6-0.md","filePath":"blog/release-v1-6-0.md"}`),d={name:"blog/release-v1-6-0.md"};function l(s,e,n,i,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-new-in-github-code-search-v1-6-0" tabindex="-1">What&#39;s new in github-code-search v1.6.0 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-6-0" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.6.0&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.6.0" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.6.0</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="global-fold-unfold-—-z" tabindex="-1">Global fold / unfold — <code>Z</code> <a class="header-anchor" href="#global-fold-unfold-—-z" aria-label="Permalink to &quot;Global fold / unfold — `Z`&quot;">​</a></h3><p>Press <strong><code>Z</code></strong> to collapse every repository in one keystroke. Press <code>Z</code> again to expand them all at once.</p><p>The logic is straightforward:</p><ul><li>If at least one repo is currently expanded, <code>Z</code> folds everything.</li><li>If every repo is already folded, <code>Z</code> unfolds everything.</li></ul><p>The cursor tracks the repository it was positioned on before the fold, so you never lose your place in the list.</p><h3 id="vim-style-top-bottom-navigation-—-gg-and-g" tabindex="-1">Vim-style top / bottom navigation — <code>gg</code> and <code>G</code> <a class="header-anchor" href="#vim-style-top-bottom-navigation-—-gg-and-g" aria-label="Permalink to &quot;Vim-style top / bottom navigation — `gg` and `G`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>gg</code></td><td>Jump to the <strong>first</strong> result</td></tr><tr><td><code>G</code></td><td>Jump to the <strong>last</strong> result</td></tr></tbody></table><p><code>gg</code> triggers on two consecutive <code>g</code> keypresses. Both shortcuts skip over section headers produced by <code>--group-by-team-prefix</code>, landing only on repo or extract rows.</p><h3 id="paged-scrolling-—-page-up-page-down-and-ctrl-u-ctrl-d" tabindex="-1">Paged scrolling — <code>Page Up</code>/<code>Page Down</code> and <code>Ctrl+U</code>/<code>Ctrl+D</code> <a class="header-anchor" href="#paged-scrolling-—-page-up-page-down-and-ctrl-u-ctrl-d" aria-label="Permalink to &quot;Paged scrolling — `Page Up`/`Page Down` and `Ctrl+U`/`Ctrl+D`&quot;">​</a></h3><p>Scroll through large result sets without holding an arrow key:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Page Up</code> / <code>Ctrl+U</code></td><td>Scroll up one page</td></tr><tr><td><code>Page Down</code> / <code>Ctrl+D</code></td><td>Scroll down one page</td></tr></tbody></table><p>Page size is computed from the actual terminal height, so the jump covers exactly what is visible on screen.</p><h3 id="open-in-browser-—-o" tabindex="-1">Open-in-browser — <code>o</code> <a class="header-anchor" href="#open-in-browser-—-o" aria-label="Permalink to &quot;Open-in-browser — `o`&quot;">​</a></h3><p>Press <strong><code>o</code></strong> on any focused row to open the corresponding page directly in your default browser — no copy-paste required.</p><table tabindex="0"><thead><tr><th>Row type</th><th>Opens</th></tr></thead><tbody><tr><td>Repo row</td><td>The GitHub repository page</td></tr><tr><td>Extract row</td><td>The exact file in the repository</td></tr></tbody></table><p>Works on macOS (<code>open</code>), Linux (<code>xdg-open</code>), and Windows (<code>cmd /c start</code>).</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or grab the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.6.0" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>',23)])])}const y=t(d,[["render",l]]);export{m as __pageData,y as default};
